mapper.select:
SELECT ${groupExpr} AS bucket,
       COUNT(*) AS rowCount,
       COALESCE(SUM(total_amount), 0) AS totalAmount
FROM bank_pay_order
WHERE deleted = 0
  AND tenant_id = #{tenantId}

    AND account_no = #{accountNo}


    AND status = #{status}


    AND apply_time >= #{startTime}


    AND apply_time < #{endTime}

GROUP BY ${groupExpr}
ORDER BY bucket
LIMIT #{limit}
